/**
 * Habit accessories: things a pet starts wearing because of how you eat.
 *
 * Nothing here is stored. Each accessory is worked out from the food journal (getPetJournal), so it
 * needs no API or database change, and it goes away again if the meals that earned it are deleted.
 *
 * The drawings live in public/pets/accessories/<pet>-<accessory>.png and are generated by
 * scripts/pets/pets.html. Only the pets listed in ART have drawings so far.
 */
import { useSyncExternalStore } from 'react';
import { getPetJournal } from './api.js';

const bostonHour = (iso) =>
  Number(new Intl.DateTimeFormat('en-US', { timeZone: 'America/New_York', hour: 'numeric', hourCycle: 'h23' }).format(new Date(iso)));

/** Each habit: which meals count toward it, and how to say why the pet is wearing it. */
export const HABITS = {
  nightcap: {
    label: 'Nightcap',
    counts: (entry) => {
      const h = bostonHour(entry.visited_at);
      return h >= 22 || h < 4;
    },
    why: (n) => `${n} late-night ${n === 1 ? 'meal' : 'meals'} (after 10 pm)`,
  },
  coffee: {
    label: 'Coffee cup',
    counts: (entry) => /cafe|café|coffee|tea|bakery/i.test(entry.place?.cuisine ?? ''),
    why: (n) => `${n} cafe ${n === 1 ? 'visit' : 'visits'}`,
  },
};

/** Which accessories have been drawn for which pet. */
const ART = {
  starter: ['nightcap', 'coffee'],
  'back-bay': ['nightcap', 'coffee'],
  cambridge: ['coffee'],
};

/** The starter eats everywhere, so it has to work a little harder than a neighborhood pet. */
const needed = (petId) => (petId === 'starter' ? 2 : 1);

/**
 * @param {Array} entries every meal, with `place` (from getPetJournal('starter'))
 * @returns {Record<string, Array<{id: string, label: string, image: string, why: string}>>} by pet id
 */
export function accessoriesFor(entries) {
  const out = {};
  for (const [petId, ids] of Object.entries(ART)) {
    const mine = petId === 'starter' ? entries : entries.filter((e) => e.place?.neighborhood?.id === petId);
    const worn = [];
    for (const id of ids) {
      const habit = HABITS[id];
      const n = mine.filter(habit.counts).length;
      if (n >= needed(petId)) {
        worn.push({ id, label: habit.label, image: `/pets/accessories/${petId}-${id}.png`, why: habit.why(n) });
      }
    }
    if (worn.length) out[petId] = worn;
  }
  return out;
}

/* A tiny shared store, so every drawing of a pet shows the same accessories without each screen fetching them. */
let current = {};
let loaded = false;
const listeners = new Set();

export async function refreshAccessories() {
  loaded = true;
  try {
    const journal = await getPetJournal('starter');
    current = accessoriesFor(journal.entries);
  } catch {
    current = {};
  }
  listeners.forEach((fn) => fn());
}

const subscribe = (fn) => {
  listeners.add(fn);
  if (!loaded) refreshAccessories();
  return () => listeners.delete(fn);
};
const NONE = [];

/** What a pet is wearing right now. */
export function usePetAccessories(petId) {
  const all = useSyncExternalStore(subscribe, () => current);
  return all[petId] ?? NONE;
}
